1	// Acceptance test for the change request:
2	//   "Let me tuck away clients I no longer work with. They should drop off my list and my search.
3	//    I do not want to lose them. Note it when I do."
4	//
5	// Archiving a client is a NON-destructive "tuck away". Each client row on the clients list offers a
6	// control to archive it (client-archive-<id>). Archiving:
7	//   * drops the client from the clients list (clients-table / client-row-<id>),
8	//   * drops it from the name search too (it never comes back as a search result),
9	//   * is held by the SERVER (it survives a fresh load),
10	//   * keeps a record — exactly one audit record `CLIENT_ARCHIVED id=<id>` per archive,
11	//   * LOSES NOTHING: the client still exists — its detail page is still reachable at /clients/<id>
12	//     with its data intact (the request is "drop off my list and my search", not "delete").
13	// Archiving one client must not touch the others, and merely viewing or searching the list records
14	// nothing — only the archive action itself does.
15	//
16	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
17	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients`
18	// honours { id, name, email, archived } and `projects` honours { id, name, clientId }.
19	import { test, expect, type Page } from '@playwright/test';
20	import { resetAndSeed } from '../support/seed';
21	import { auditLines } from '../support/audit';
22	
23	const clientRows = (page: Page) => page.locator('[data-testid^="client-row-"]');
24	
25	// The audit record for one archive — carries the client's id and nothing else; matched exactly.
26	const archivedRecord = (id: number) => `CLIENT_ARCHIVED id=${id}`;
27	
28	const archivedRecordsFor = (id: number): string[] =>
29	  auditLines().filter((line) => line === archivedRecord(id));
30	
31	test.describe('Archive a client', () => {
32	  test('archiving a client drops it from the list, persists, keeps the client, and records it once', async ({
33	    page,
34	  }) => {
35	    await resetAndSeed({
36	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
37	      // A project for this client — kept so we can prove the client itself is NOT lost afterwards.
38	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
39	    });
40	
41	    await page.goto('/clients');
42	    await expect(page.getByTestId('clients-page')).toBeVisible();
43	
44	    // The client is listed and offers a control to archive it.
45	    await expect(clientRows(page)).toHaveCount(1);
46	    await expect(page.getByTestId('client-row-1')).toBeVisible();
47	    const archive = page.getByTestId('client-archive-1');
48	    await expect(archive).toBeVisible();
49	
50	    // Nothing has been recorded yet — reset clears the audit file, so the record below is proof the
51	    // archiving (not the seeding) wrote it.
52	    expect(auditLines()).toEqual([]);
53	
54	    await archive.click();
55	
56	    // The client drops off the list — tucked away, it is the only client so the list is now empty.
57	    await expect(page.getByTestId('client-row-1')).toHaveCount(0);
58	    await expect(clientRows(page)).toHaveCount(0);
59	    await expect(page.getByTestId('clients-empty')).toBeVisible();
60	
61	    // Exactly one record was kept for this archive, carrying the client's id.
62	    expect(archivedRecordsFor(1)).toHaveLength(1);
63	    expect(auditLines()).toHaveLength(1);
64	
65	    // The tuck-away is held by the server, not just the page: it survives a fresh load, and merely
66	    // viewing the list does not record the archive a second time.
67	    await page.reload();
68	    await expect(page.getByTestId('client-row-1')).toHaveCount(0);
69	    await expect(page.getByTestId('clients-empty')).toBeVisible();
70	    expect(archivedRecordsFor(1)).toHaveLength(1);
71	    expect(auditLines()).toHaveLength(1);
72	
73	    // Nothing was lost: the client was tucked away, not deleted. Its detail page is still reachable
74	    // at /clients/<id> and still carries its data (the project done for it). Opening it is a view —
75	    // it records nothing.
76	    await page.goto('/clients/1');
77	    await expect(page.getByTestId('client-detail-page')).toBeVisible();
78	    await expect(page.getByTestId('project-row-1').getByTestId('project-name')).toHaveText(
79	      'Website Redesign',
80	    );
81	    expect(archivedRecordsFor(1)).toHaveLength(1);
82	    expect(auditLines()).toHaveLength(1);
83	  });
84	
85	  test('archiving one client leaves the others on the list, and each archive keeps its own record', async ({
86	    page,
87	  }) => {
88	    await resetAndSeed({
89	      clients: [
90	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
91	        { id: 2, name: 'Globex', email: 'contact@globex.test' },
92	        { id: 3, name: 'Initech', email: 'info@initech.test' },
93	      ],
94	    });
95	
96	    await page.goto('/clients');
97	    await expect(clientRows(page)).toHaveCount(3);
98	    expect(auditLines()).toEqual([]);
99	
100	    // Archive the middle client.
101	    await page.getByTestId('client-archive-2').click();
102	
103	    // Only that client is tucked away; its siblings remain, each still carrying its name and email.
104	    await expect(page.getByTestId('client-row-2')).toHaveCount(0);
105	    await expect(clientRows(page)).toHaveCount(2);
106	    await expect(page.getByTestId('client-row-1').getByTestId('client-name')).toHaveText('Acme Corp');
107	    await expect(page.getByTestId('client-row-1').getByTestId('client-email')).toHaveText(
108	      'hello@acme.test',
109	    );
110	    await expect(page.getByTestId('client-row-3').getByTestId('client-name')).toHaveText('Initech');
111	
112	    // Exactly one record so far, for the client that was archived.
113	    expect(archivedRecordsFor(2)).toHaveLength(1);
114	    expect(auditLines()).toHaveLength(1);
115	
116	    // Archive another client — a second record is kept, independent of the first.
117	    await page.getByTestId('client-archive-1').click();
118	    await expect(page.getByTestId('client-row-1')).toHaveCount(0);
119	    await expect(clientRows(page)).toHaveCount(1);
120	    await expect(page.getByTestId('client-row-3')).toBeVisible();
121	
122	    expect(archivedRecordsFor(2)).toHaveLength(1);
123	    expect(archivedRecordsFor(1)).toHaveLength(1);
124	    expect(auditLines()).toHaveLength(2);
125	
126	    // The tuck-aways survive a fresh load: only the un-archived client remains on the list, and
127	    // reloading records nothing more.
128	    await page.reload();
129	    await expect(clientRows(page)).toHaveCount(1);
130	    await expect(page.getByTestId('client-row-3')).toBeVisible();
131	    await expect(page.getByTestId('client-row-1')).toHaveCount(0);
132	    await expect(page.getByTestId('client-row-2')).toHaveCount(0);
133	    expect(auditLines()).toHaveLength(2);
134	  });
135	
136	  test('archiving a client also drops it from the name search', async ({ page }) => {
137	    await resetAndSeed({
138	      clients: [
139	        // Two clients share the "Acme" name so a search for it would match both.
140	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
141	        { id: 2, name: 'Acme Industries', email: 'ops@acme-ind.test' },
142	        { id: 3, name: 'Globex', email: 'contact@globex.test' },
143	      ],
144	    });
145	
146	    await page.goto('/clients');
147	    await expect(clientRows(page)).toHaveCount(3);
148	
149	    // Both Acme clients match the search before anything is archived.
150	    const search = page.getByTestId('client-search');
151	    await search.fill('acme');
152	    await expect(clientRows(page)).toHaveCount(2);
153	    await expect(page.getByTestId('client-row-1')).toBeVisible();
154	    await expect(page.getByTestId('client-row-2')).toBeVisible();
155	
156	    // Clear the box, archive one of the Acme clients, then search again.
157	    await search.fill('');
158	    await page.getByTestId('client-archive-1').click();
159	    await expect(page.getByTestId('client-row-1')).toHaveCount(0);
160	
161	    // The search now only returns the remaining Acme client — the archived one never comes back,
162	    // even as a search result.
163	    await search.fill('acme');
164	    await expect(clientRows(page)).toHaveCount(1);
165	    await expect(page.getByTestId('client-row-2')).toBeVisible();
166	    await expect(page.getByTestId('client-row-1')).toHaveCount(0);
167	
168	    // Searching precisely for the archived client's name yields nothing.
169	    await search.fill('Acme Corp');
170	    await expect(clientRows(page)).toHaveCount(0);
171	    await expect(page.getByTestId('client-row-1')).toHaveCount(0);
172	
173	    // Exactly one archive happened.
174	    expect(archivedRecordsFor(1)).toHaveLength(1);
175	    expect(auditLines()).toHaveLength(1);
176	  });
177	
178	  test('a client seeded archived starts off both the list and the search, and seeding records nothing', async ({
179	    page,
180	  }) => {
181	    await resetAndSeed({
182	      clients: [
183	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
184	        // Already tucked away: it must not show on the list or in the search.
185	        { id: 2, name: 'Globex', email: 'contact@globex.test', archived: true },
186	      ],
187	    });
188	
189	    await page.goto('/clients');
190	    await expect(page.getByTestId('clients-page')).toBeVisible();
191	
192	    // Only the un-archived client is listed; the archived one is off the list entirely.
193	    await expect(clientRows(page)).toHaveCount(1);
194	    await expect(page.getByTestId('client-row-1')).toBeVisible();
195	    await expect(page.getByTestId('client-row-1').getByTestId('client-name')).toHaveText('Acme Corp');
196	    await expect(page.getByTestId('client-row-2')).toHaveCount(0);
197	    await expect(page.getByTestId('clients-page')).not.toContainText('Globex');
198	
199	    // Seeding an archived client is not an archive action — nothing is recorded.
200	    expect(auditLines()).toEqual([]);
201	
202	    // And it is absent from the search as well: searching for its name returns no rows.
203	    await page.getByTestId('client-search').fill('Globex');
204	    await expect(clientRows(page)).toHaveCount(0);
205	    await expect(page.getByTestId('client-row-2')).toHaveCount(0);
206	
207	    // Searching for the active client still finds it, proving the search itself works.
208	    await page.getByTestId('client-search').fill('Acme');
209	    await expect(clientRows(page)).toHaveCount(1);
210	    await expect(page.getByTestId('client-row-1')).toBeVisible();
211	
212	    // Still nothing recorded — searching is a view.
213	    expect(auditLines()).toEqual([]);
214	  });
215	});
